"use strict";
window.CampaignRepository=CampaignWorld.repository(localStorage,ArdennesCommand,ArdennesSpatial);
window.CampaignRepository.load();
const CampaignWorldView=(()=>{
 const C=CampaignWorld,R=window.CampaignRepository,mission=new URLSearchParams(location.search).get('worldMission');let level=mission?'formation':'campaign',unit=null,notice='',refresh=()=>{},viewTime=0;
 const el=(t,text)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;return n;};
 const svg=(t,a,text)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',t);for(const[k,v]of Object.entries(a))n.setAttribute(k,v);if(text)n.textContent=text;return n;};
 const button=(text,fn)=>{const b=el('button',text);b.onclick=fn;return b;};
 function definition(){const w=R.get();if(!w)return null;if(mission&&!w.missions[mission]){const source=window.PANZER_SITUATION_LIBRARY.find(d=>d.situation.number===(mission==='M14'?14:15));if(!['M14','M15'].includes(mission)||!w.operation.missions[mission]?.choice)return null;R.save(C.bindMission(w,mission,source,ArdennesCommand));}return R.get();}
 function bounds(){const w=definition(),m=w?.missions[mission];if(level==='campaign'||!m)return[0,0,1000,420];const f=m.footprint;if(level==='formation')return f.map(x=>x/40);const focus=unit&&m.placements[unit]?.position||[f[0]+f[2]/2,f[1]+f[3]/2];return[(focus[0]-600)/40,(focus[1]-450)/40,30,22.5];}
 function controls(host,onRefresh,onFit){refresh=onRefresh;if(document.getElementById('worldScale'))return;const label=el('label','World scale '),select=el('select');select.id='worldScale';select.setAttribute('aria-label','World scale');for(const [v,t]of [['campaign','Campaign area (1 km grid)'],...(mission?[['formation','Formation Situation (250 m hexes)'],['tactical','ASL terrain preview (40 m hexes)']]:[])]){const o=el('option',t);o.value=v;select.append(o);}select.value=level;select.onchange=()=>{level=select.value;onFit(bounds());refresh();};label.append(select);host.append(label);}
 function draw(canvas,s,time){viewTime=time;const w=definition();if(!w)return;const b=bounds().map(x=>x*40),size=level==='campaign'?1000:level==='formation'?250:40;
 canvas.append(svg('rect',{x:b[0]/40,y:b[1]/40,width:b[2]/40,height:b[3]/40,fill:'#ede7c9'}));
 // Woodland footprints are world features independent of requested hex size.
 for(let a=Math.floor(b[0]/1000)-1;a<=(b[0]+b[2])/1000+1;a++)for(let j=Math.floor(b[1]/1000)-1;j<=(b[1]+b[3])/1000+1;j++){const h=C.hash(w.mapSeed+'|'+w.generator+'|'+a+'|'+j);if(h%3===0)canvas.append(svg('circle',{cx:(a*1000+h%800)/40,cy:(j*1000+(h>>>10)%800)/40,r:(250+h%450)/40,fill:'#b0bf88','pointer-events':'none'}));}
 for(const event of w.terrainEvents.filter(e=>e.area&&e.at<=time))canvas.append(svg('circle',{cx:event.area.x/40,cy:event.area.y/40,r:event.area.radius/40,fill:event.terrain==='woods'?'#b0bf88':'#ede7c9','pointer-events':'none'}));
 for(const c of C.cells(w,b,size,time)){const poly=svg('polygon',{points:Array.from({length:6},(_,i)=>{const a=i*Math.PI/3+Math.PI/6;return[(c.x+c.r*Math.cos(a))/40,(c.y+c.r*Math.sin(a))/40].join(',');}).join(' '),fill:'transparent',stroke:'#b5b28c','stroke-width':level==='tactical'?.035:.15});if(mission&&level==='formation'){poly.setAttribute('role','button');poly.setAttribute('tabindex','0');poly.setAttribute('aria-label','Deploy to world hex '+c.id);poly.onclick=e=>{e.stopPropagation();try{if(!unit)throw Error('Select a unit first.');R.save(C.place(R.get(),mission,unit,c.id,viewTime));notice='Placed '+R.get().forces[unit].type.label+' at '+c.id;}catch(e){notice=e.message;}refresh();};poly.onkeydown=e=>{if(e.key==='Enter')poly.onclick(e);};if(unit){const m=w.missions[mission],allied=w.forces[unit].side==='Allied';if((c.x<m.footprint[0]+m.footprint[2]/2)===allied)poly.setAttribute('fill','#b7772525');}}canvas.append(poly);}
 for(const feature of [w.river,...Object.values(w.routes)]){const changed=w.terrainEvents.filter(e=>e.featureId===feature.id&&e.at<=time).at(-1);canvas.append(svg('polyline',{points:feature.points.map(p=>p.map(x=>x/40).join(',')).join(' '),fill:'none',stroke:changed?.state==='destroyed'?'#8a3b2a':feature.id==='river-main'?'#78a7b5':'#a08048','stroke-width':feature.id==='river-main'?2:1,'stroke-dasharray':changed?.state==='destroyed'?'2 2':'none','pointer-events':'none'}));}
 for(const [id,m]of Object.entries(w.missions)){const f=m.footprint;canvas.append(svg('rect',{x:f[0]/40,y:f[1]/40,width:f[2]/40,height:f[3]/40,fill:'none',stroke:'#b77725','stroke-width':.6,'stroke-dasharray':'2 2','pointer-events':'none'}));for(const [uid,p]of Object.entries(C.placementsAt(m,time))){const u=w.forces[uid],g=svg('g',{transform:`translate(${p.position[0]/40} ${p.position[1]/40})`,role:'button',tabindex:0,'aria-label':u.type.label+' '+u.sourceInstance});g.append(svg('rect',{x:-2.5,y:-2.5,width:5,height:5,fill:u.side==='Allied'?'#c6d395':'#bad1db',stroke:uid===unit?'#b77725':'#243025','stroke-width':.25}),svg('text',{x:0,y:.5,'text-anchor':'middle','font-size':.9},u.type.label));g.onclick=e=>{e.stopPropagation();unit=uid;refresh();};canvas.append(g);}}
 }
 function panel(root,isLive){if(!mission)return false;root.replaceChildren();const w=definition(),m=w?.missions[mission];root.append(el('h2','Campaign Situation setup'));if(!m){root.append(el('p','Commit this mission at its headquarters first.'));return true;}const back=el('a','Return to campaign headquarters');back.href='index.html?exercise=ardennes';root.append(back,el('p',w.title+' | '+m.title),el('p','Seed '+w.mapSeed.slice(0,12)+' | '+w.generator),el('p','Mission starts 18 December 1944 '+ArdennesCommand.clock(m.startTime)+'. Units retain campaign identities and the committed supply allocation.'),el('p',m.adaptation));
 root.append(el('p','Footprint: '+m.footprint[0]+' m east, '+m.footprint[1]+' m south of campaign origin | 8 km by 6 km. Shared EPSG:3035 coordinate basis.'));
 if(!isLive){root.append(el('p','Historical/forecast inspection only. Return to current time to deploy.'));return true;}if(level==='campaign'){root.append(el('p','Choose Formation Situation in World scale to deploy this mission.'));return true;}if(level==='tactical'){root.append(el('p','40 m terrain preview of this same world. Formation counters have not been decomposed into squads. No ASL Scenario Card is admitted.'));return true;}
 const placed=Object.keys(m.placements).length;root.append(el('p',placed+' / '+m.units.length+' counters placed. Allied deploy west; German deploy east. One counter per hex in this prototype.'));
 const select=el('select');select.setAttribute('aria-label','Campaign unit to deploy');const placeholder=el('option','Select a unit');placeholder.value='';select.append(placeholder);for(const uid of m.units){const u=w.forces[uid],o=el('option',u.side+' | '+u.type.label+' | '+u.sourceInstance+(m.placements[uid]?' (placed)':''));o.value=uid;select.append(o);}select.value=unit||'';select.disabled=m.ready;select.onchange=()=>{unit=select.value;refresh();};root.append(select);const msg=el('p',notice||'Select a unit, then select a hex in its highlighted deployment half.');msg.setAttribute('role','status');root.append(msg);
 const done=button(m.ready?'Deployment locked':'Complete deployment',()=>{const current=R.get(),mm=current.missions[mission];if(Object.keys(mm.placements).length!==mm.units.length)return;R.save({...current,missions:{...current.missions,[mission]:{...mm,ready:true}}});refresh();});done.disabled=m.ready||placed!==m.units.length;root.append(done,el('p','Combat is blocked until objectives, board-specific rules and tactical admission are adapted to this footprint. The source card remains in Map Utilities.'));
 return true;}
 return{bounds,draw,controls,panel,mission};
})();
window.CampaignWorldViewHandle=CampaignWorldView;

// The overview uses the same coordinate transform and feature records as the local views.
(()=>{const w=window.CampaignRepository.get();if(!w||new URLSearchParams(location.search).has('exercise'))return;const root=document.getElementById('map');if(!root)return;const ns='http://www.w3.org/2000/svg',g=document.createElementNS(ns,'g');g.id='campaignWorldFootprint';const rect=document.createElementNS(ns,'rect');rect.setAttribute('x',w.atlasOrigin[0]);rect.setAttribute('y',w.atlasOrigin[1]);rect.setAttribute('width',40);rect.setAttribute('height',16.8);rect.setAttribute('fill','#ede7c9');rect.setAttribute('stroke','#b77725');rect.setAttribute('stroke-width','1');g.append(rect);const terrain=document.createElementNS(ns,'g');terrain.setAttribute('transform',`translate(${w.atlasOrigin[0]} ${w.atlasOrigin[1]}) scale(.04)`);const defs=document.createElementNS(ns,'defs'),clip=document.createElementNS(ns,'clipPath'),clipRect=document.createElementNS(ns,'rect');clip.id='campaignOverviewClip';clipRect.setAttribute('width','1000');clipRect.setAttribute('height','420');clip.append(clipRect);defs.append(clip);terrain.append(defs);const surface=document.createElementNS(ns,'g');surface.setAttribute('clip-path','url(#campaignOverviewClip)');CampaignWorldView.draw(surface,w.operation,w.operation.time);terrain.append(surface);g.append(terrain);for(const f of [w.river,...Object.values(w.routes)]){const line=document.createElementNS(ns,'polyline');line.setAttribute('points',f.points.map(p=>CampaignWorld.atlasPoint(w,p).join(',')).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke',f.id==='river-main'?'#78a7b5':'#a08048');line.setAttribute('stroke-width','.12');g.append(line);}g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label','Open active Ardennes campaign world');g.onclick=()=>location.href='index.html?exercise=ardennes';g.onkeydown=e=>{if(e.key==='Enter')g.onclick();};root.append(g);const button=document.createElement('button');button.textContent='Locate active campaign world';button.onclick=()=>{view=[w.atlasOrigin[0]-30,w.atlasOrigin[1]-20,100,65];renderView();};document.getElementById('gameControls').prepend(button);})();
